/**
 * Kotlin Code Generator — Deterministic code generation from handoff package
 *
 * ref: P12-001
 *
 * Input: ImplementationHandoffPackage (from handoff_package.json)
 * Output: Kotlin source files (entities, DTOs, enums, state machine validators,
 *         conflict policy mapping, conflict policy tests)
 *
 * CONSTRAINTS:
 * - Input is ONLY handoff_package.json. No access to upstream P10 artifacts.
 * - Unknown type → generation failure (no silent String fallback).
 * - All generated files include provenance header.
 * - All field names, enum values, state machine transitions are 1:1 with handoff.
 */

import type {
  ImplementationHandoffPackage,
  DataModelSpec,
  DataModelField,
  StateMachineSpec,
  ConflictPolicyEntry,
} from "../handoff/types.js";
import { createHash } from "node:crypto";

// ---------------------------------------------------------------------------
// Type Mapping
// ---------------------------------------------------------------------------

/**
 * Deterministic mapping from handoff type strings to Kotlin types.
 * If a type is not in this map, generation MUST fail.
 */
const TYPE_MAP: Record<string, string> = {
  // Primitives
  "String": "String",
  "String (UUID)": "String",
  "String (ISO-8601)": "String",
  "Int": "Int",
  "Int?": "Int?",
  "Long": "Long",
  "Boolean": "Boolean",
  "Double": "Double",

  // Collections
  "Map<String, Int>": "Map<String, Int>",
  "List<String>": "List<String>",
  "List<RemoteChange>": "List<RemoteChange>",

  // Domain types (serialized as String in Room, typed in DTOs)
  "TriageResult": "TriageResult",
  "ReportSnapshot": "ReportSnapshot",
  "OfflineReportEnvelope": "OfflineReportEnvelope",
  "ConflictPayload": "ConflictPayload",
  "VectorClock": "VectorClock",

  // State enums (stored as String in Room)
  "PendingReportState": "PendingReportState",
  "SyncOperationState": "SyncOperationState",
  "ConflictResolutionState": "ConflictResolutionState",
  "ConflictType": "ConflictType",
};

/**
 * Resolve a handoff type to Kotlin. Throws on unknown type.
 */
function resolveType(handoffType: string, nullable: boolean): string {
  const base = TYPE_MAP[handoffType];
  if (!base) {
    throw new Error(
      `[P12] Unknown type '${handoffType}' — cannot generate Kotlin. ` +
      `Add it to TYPE_MAP or fix the handoff package.`
    );
  }
  // If the type already has ?, don't double-add
  if (nullable && !base.endsWith("?")) return `${base}?`;
  return base;
}

// ---------------------------------------------------------------------------
// Name Conversion
// ---------------------------------------------------------------------------

/** snake_case → camelCase */
function toCamelCase(s: string): string {
  return s.replace(/_([a-z])/g, (_, c) => c.toUpperCase());
}

/** snake_case → UPPER_SNAKE_CASE */
function toUpperSnake(s: string): string {
  return s.toUpperCase();
}

// ---------------------------------------------------------------------------
// Provenance Header
// ---------------------------------------------------------------------------

function generateHeader(
  pkg: ImplementationHandoffPackage,
  fileName: string,
  pkgHash: string,
): string {
  const lines = [
    "// ═══════════════════════════════════════════════════════════════",
    `// Generated by Pantheon Phase 12 — Deterministic Kotlin Codegen`,
    `// File: ${fileName}`,
    `// Source: handoff_package.json`,
    `// Package ID: ${pkg.package_id}`,
    `// Package Hash: ${pkgHash}`,
    `// Generated: ${new Date().toISOString()}`,
    "// DO NOT EDIT MANUALLY — regenerate from handoff package.",
    "// ═══════════════════════════════════════════════════════════════",
    "",
  ];
  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// Enum Generation
// ---------------------------------------------------------------------------

function generateEnums(pkg: ImplementationHandoffPackage): string {
  const parts: string[] = [];

  // State machine enums
  for (const sm of pkg.state_machines) {
    parts.push(`enum class ${sm.name} {`);
    parts.push(sm.states.map(s => `    ${s}`).join(",\n"));
    parts.push("}\n");
  }

  // Contract definition enums
  for (const cd of pkg.contract_definitions) {
    if (cd.enum_values && cd.enum_values.length > 0) {
      // Convert term to PascalCase enum name
      const enumName = cd.term
        .split("_")
        .map(w => w.charAt(0).toUpperCase() + w.slice(1))
        .join("");
      // Skip if already generated via state machine
      if (pkg.state_machines.some(sm => sm.name === enumName)) continue;

      parts.push(`enum class ${enumName} {`);
      parts.push(cd.enum_values.map(ev => `    ${ev.value}`).join(",\n"));
      parts.push("}\n");
    }
  }

  // ConflictPolicy enum (from matrix policies)
  const policies = new Set<string>();
  for (const cpm of pkg.conflict_policy_matrix) {
    policies.add(cpm.policy);
  }
  parts.push("enum class ConflictPolicy {");
  parts.push([...policies].map(p => `    ${p}`).join(",\n"));
  parts.push("}\n");

  return parts.join("\n");
}

// ---------------------------------------------------------------------------
// Entity Generation
// ---------------------------------------------------------------------------

function generateEntity(model: DataModelSpec): string {
  const lines: string[] = [];

  // Explicit table name mapping (deterministic from handoff spec)
  const tableNameMap: Record<string, string> = {
    "PendingReportEntity": "pending_reports",
    "SyncOperationEntity": "sync_operations",
    "RetryLedgerEntry": "retry_ledger",
    "ConflictRecordEntity": "conflict_records",
    "VectorClockEntry": "vector_clock_entries",
    "AuditEventEntity": "audit_events",
  };
  const resolvedTable = tableNameMap[model.name];
  if (!resolvedTable) {
    throw new Error(`[P12] Unknown entity '${model.name}' — no table name mapping.`);
  }

  lines.push(`@Entity(tableName = "${resolvedTable}")`);
  lines.push(`data class ${model.name}(`);

  const fieldLines: string[] = [];
  for (const f of model.fields) {
    const annotations: string[] = [];
    if (f.primary_key) annotations.push("@PrimaryKey");
    if (f.indexed) annotations.push(`@ColumnInfo(name = "${f.name}", index = true)`);
    else annotations.push(`@ColumnInfo(name = "${f.name}")`);

    const ktType = resolveType(f.type, f.nullable);
    const propName = toCamelCase(f.name);
    const annStr = annotations.length > 0 ? annotations.join(" ") + " " : "";
    fieldLines.push(`    ${annStr}val ${propName}: ${ktType}`);
  }
  lines.push(fieldLines.join(",\n"));
  lines.push(")");

  // Invariants as comments
  if (model.invariants.length > 0) {
    lines.push("");
    lines.push("/*");
    lines.push(" * Invariants:");
    for (const inv of model.invariants) {
      lines.push(` *   - ${inv}`);
    }
    lines.push(" */");
  }

  return lines.join("\n");
}

function generateEntities(pkg: ImplementationHandoffPackage): string {
  const parts: string[] = ["import androidx.room.*\n"];

  const entities = pkg.data_models.filter(dm => dm.kind === "room_entity");
  for (const e of entities) {
    parts.push(generateEntity(e));
    parts.push("");
  }

  return parts.join("\n");
}

// ---------------------------------------------------------------------------
// DTO Generation
// ---------------------------------------------------------------------------

function generateDto(model: DataModelSpec): string {
  const lines: string[] = [];

  lines.push(`data class ${model.name}(`);

  const fieldLines: string[] = [];
  for (const f of model.fields) {
    const ktType = resolveType(f.type, f.nullable);
    const propName = toCamelCase(f.name);
    fieldLines.push(`    val ${propName}: ${ktType}`);
  }
  lines.push(fieldLines.join(",\n"));
  lines.push(")");

  // Invariants
  if (model.invariants.length > 0) {
    lines.push("");
    lines.push("/*");
    lines.push(" * Invariants:");
    for (const inv of model.invariants) {
      lines.push(` *   - ${inv}`);
    }
    lines.push(" */");
  }

  return lines.join("\n");
}

function generateDtos(pkg: ImplementationHandoffPackage): string {
  const parts: string[] = [];

  const dtos = pkg.data_models.filter(dm => dm.kind === "network_dto");
  for (const d of dtos) {
    parts.push(generateDto(d));
    parts.push("");
  }

  return parts.join("\n");
}

// ---------------------------------------------------------------------------
// State Machine Validator Generation
// ---------------------------------------------------------------------------

function generateStateMachineValidator(sm: StateMachineSpec): string {
  const lines: string[] = [];
  const enumName = sm.name;

  // Allowed transitions set
  lines.push(`object ${enumName}Machine {`);
  lines.push("");
  lines.push(`    private val allowedTransitions: Set<Pair<${enumName}, ${enumName}>> = setOf(`);
  for (let i = 0; i < sm.allowed_transitions.length; i++) {
    const t = sm.allowed_transitions[i];
    const comma = i < sm.allowed_transitions.length - 1 ? "," : "";
    lines.push(`        Pair(${enumName}.${t.from}, ${enumName}.${t.to})${comma}`);
  }
  lines.push("    )");
  lines.push("");

  // Forbidden transitions set
  lines.push(`    private val forbiddenTransitions: Set<Pair<${enumName}, ${enumName}>> = setOf(`);
  for (let i = 0; i < sm.forbidden_transitions.length; i++) {
    const t = sm.forbidden_transitions[i];
    const comma = i < sm.forbidden_transitions.length - 1 ? "," : "";
    lines.push(`        Pair(${enumName}.${t.from}, ${enumName}.${t.to})${comma}`);
  }
  lines.push("    )");
  lines.push("");

  // Audit-required transitions
  const auditTransitions = sm.allowed_transitions.filter(t => t.audit_event_required);
  lines.push(`    private val auditRequiredTransitions: Set<Pair<${enumName}, ${enumName}>> = setOf(`);
  for (let i = 0; i < auditTransitions.length; i++) {
    const t = auditTransitions[i];
    const comma = i < auditTransitions.length - 1 ? "," : "";
    lines.push(`        Pair(${enumName}.${t.from}, ${enumName}.${t.to})${comma}`);
  }
  lines.push("    )");
  lines.push("");

  // Validator functions
  lines.push(`    fun isAllowed(from: ${enumName}, to: ${enumName}): Boolean {`);
  lines.push("        return Pair(from, to) in allowedTransitions");
  lines.push("    }");
  lines.push("");
  lines.push(`    fun isForbidden(from: ${enumName}, to: ${enumName}): Boolean {`);
  lines.push("        return Pair(from, to) in forbiddenTransitions");
  lines.push("    }");
  lines.push("");
  lines.push(`    fun requiresAudit(from: ${enumName}, to: ${enumName}): Boolean {`);
  lines.push("        return Pair(from, to) in auditRequiredTransitions");
  lines.push("    }");
  lines.push("");
  lines.push(`    fun requireAllowedTransition(from: ${enumName}, to: ${enumName}) {`);
  lines.push(`        if (isForbidden(from, to)) {`);
  lines.push(`            throw IllegalStateException("Forbidden transition: \$from -> \$to")`);
  lines.push("        }");
  lines.push(`        if (!isAllowed(from, to)) {`);
  lines.push(`            throw IllegalStateException("Unknown transition: \$from -> \$to")`);
  lines.push("        }");
  lines.push("    }");
  lines.push("}");

  return lines.join("\n");
}

function generateStateMachines(pkg: ImplementationHandoffPackage): string {
  const parts: string[] = [];

  for (const sm of pkg.state_machines) {
    parts.push(generateStateMachineValidator(sm));
    parts.push("");
  }

  return parts.join("\n");
}

// ---------------------------------------------------------------------------
// Conflict Policy Mapping Generation
// ---------------------------------------------------------------------------

function generateConflictPolicy(pkg: ImplementationHandoffPackage): string {
  const lines: string[] = [];

  lines.push("object ConflictPolicyRegistry {");
  lines.push("");
  lines.push("    /**");
  lines.push("     * Returns the conflict policy for a given field group.");
  lines.push("     * Source: handoff_package.json conflict_policy_matrix");
  lines.push("     */");
  lines.push("    fun getPolicy(fieldGroup: String): ConflictPolicy {");
  lines.push("        return when (fieldGroup) {");
  for (const cpm of pkg.conflict_policy_matrix) {
    lines.push(`            "${cpm.field_group}" -> ConflictPolicy.${cpm.policy}`);
  }
  lines.push(`            else -> throw IllegalArgumentException("Unknown field group: \$fieldGroup")`);
  lines.push("        }");
  lines.push("    }");
  lines.push("");

  // Risk level mapping
  lines.push("    fun getRiskLevel(fieldGroup: String): String {");
  lines.push("        return when (fieldGroup) {");
  for (const cpm of pkg.conflict_policy_matrix) {
    lines.push(`            "${cpm.field_group}" -> "${cpm.risk_level}"`);
  }
  lines.push(`            else -> throw IllegalArgumentException("Unknown field group: \$fieldGroup")`);
  lines.push("        }");
  lines.push("    }");
  lines.push("");

  // Audit required mapping
  lines.push("    fun isAuditRequired(fieldGroup: String): Boolean {");
  lines.push("        return when (fieldGroup) {");
  for (const cpm of pkg.conflict_policy_matrix) {
    lines.push(`            "${cpm.field_group}" -> ${cpm.audit_required}`);
  }
  lines.push(`            else -> throw IllegalArgumentException("Unknown field group: \$fieldGroup")`);
  lines.push("        }");
  lines.push("    }");
  lines.push("");

  // All field groups constant
  lines.push("    val allFieldGroups: List<String> = listOf(");
  lines.push(pkg.conflict_policy_matrix.map(cpm => `        "${cpm.field_group}"`).join(",\n"));
  lines.push("    )");
  lines.push("");

  // Clinical (high-risk vector_clock) field groups
  const clinicalGroups = pkg.conflict_policy_matrix
    .filter(cpm => cpm.policy === "vector_clock" && cpm.risk_level === "high")
    .map(cpm => cpm.field_group);
  lines.push("    val clinicalFieldGroups: List<String> = listOf(");
  lines.push(clinicalGroups.map(g => `        "${g}"`).join(",\n"));
  lines.push("    )");
  lines.push("");

  // LWW-allowed field groups
  const lwwGroups = pkg.conflict_policy_matrix
    .filter(cpm => cpm.policy === "last_writer_wins")
    .map(cpm => cpm.field_group);
  lines.push("    val lwwFieldGroups: List<String> = listOf(");
  lines.push(lwwGroups.map(g => `        "${g}"`).join(",\n"));
  lines.push("    )");

  lines.push("}");

  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// Conflict Policy Test Generation
// ---------------------------------------------------------------------------

function generateConflictPolicyTests(pkg: ImplementationHandoffPackage): string {
  const lines: string[] = [];

  lines.push("import org.junit.Test");
  lines.push("import kotlin.test.assertEquals");
  lines.push("import kotlin.test.assertFailsWith");
  lines.push("");
  lines.push("class ConflictPolicyTests {");
  lines.push("");

  // Test 1: Clinical fields require vector_clock
  const clinicalGroups = pkg.conflict_policy_matrix
    .filter(cpm => cpm.policy === "vector_clock" && cpm.risk_level === "high");
  lines.push("    @Test");
  lines.push("    fun testClinicalFieldsRequireVectorClockPolicy() {");
  lines.push("        val clinicalFieldGroups = listOf(");
  lines.push(clinicalGroups.map(cpm => `            "${cpm.field_group}"`).join(",\n"));
  lines.push("        )");
  lines.push("        clinicalFieldGroups.forEach { group ->");
  lines.push("            assertEquals(ConflictPolicy.vector_clock, ConflictPolicyRegistry.getPolicy(group))");
  lines.push("        }");
  lines.push("    }");
  lines.push("");

  // Test 2: LWW only for low-risk metadata
  const lwwGroups = pkg.conflict_policy_matrix
    .filter(cpm => cpm.policy === "last_writer_wins");
  lines.push("    @Test");
  lines.push("    fun testLWWOnlyForLowRiskMetadata() {");
  lines.push("        val lwwFieldGroups = listOf(");
  lines.push(lwwGroups.map(cpm => `            "${cpm.field_group}"`).join(",\n"));
  lines.push("        )");
  lines.push("        lwwFieldGroups.forEach { group ->");
  lines.push("            assertEquals(ConflictPolicy.last_writer_wins, ConflictPolicyRegistry.getPolicy(group))");
  lines.push("        }");
  lines.push("        // Verify no high-risk group uses LWW");
  lines.push("        ConflictPolicyRegistry.clinicalFieldGroups.forEach { group ->");
  lines.push("            assertFailsWith<AssertionError> {");
  lines.push("                assertEquals(ConflictPolicy.last_writer_wins, ConflictPolicyRegistry.getPolicy(group))");
  lines.push("            }");
  lines.push("        }");
  lines.push("    }");
  lines.push("");

  // Test 3: retry_attempt_count is local_only
  const localOnlyGroups = pkg.conflict_policy_matrix
    .filter(cpm => cpm.policy === "local_only");
  lines.push("    @Test");
  lines.push("    fun testLocalOnlyFields() {");
  lines.push("        val localOnlyGroups = listOf(");
  lines.push(localOnlyGroups.map(cpm => `            "${cpm.field_group}"`).join(",\n"));
  lines.push("        )");
  lines.push("        localOnlyGroups.forEach { group ->");
  lines.push("            assertEquals(ConflictPolicy.local_only, ConflictPolicyRegistry.getPolicy(group))");
  lines.push("        }");
  lines.push("    }");
  lines.push("");

  // Test 4: sync_cursor is server_token
  const serverTokenGroups = pkg.conflict_policy_matrix
    .filter(cpm => cpm.policy === "server_token");
  lines.push("    @Test");
  lines.push("    fun testServerTokenFields() {");
  lines.push("        val serverTokenGroups = listOf(");
  lines.push(serverTokenGroups.map(cpm => `            "${cpm.field_group}"`).join(",\n"));
  lines.push("        )");
  lines.push("        serverTokenGroups.forEach { group ->");
  lines.push("            assertEquals(ConflictPolicy.server_token, ConflictPolicyRegistry.getPolicy(group))");
  lines.push("        }");
  lines.push("    }");
  lines.push("");

  // Test 5: Forbidden state transitions
  lines.push("    @Test");
  lines.push("    fun testForbiddenStateTransitions() {");
  for (const sm of pkg.state_machines) {
    lines.push(`        // ${sm.name}`);
    for (const ft of sm.forbidden_transitions) {
      lines.push(`        assertFailsWith<IllegalStateException> {`);
      lines.push(`            ${sm.name}Machine.requireAllowedTransition(${sm.name}.${ft.from}, ${sm.name}.${ft.to})`);
      lines.push(`        }`);
    }
  }
  lines.push("    }");
  lines.push("");

  // Test 6: ConflictPayload required fields
  const cpDef = pkg.contract_definitions.find(cd => cd.term === "conflict_payload");
  if (cpDef?.fields) {
    const required = cpDef.fields.filter(f => f.required);
    lines.push("    @Test");
    lines.push("    fun testConflictPayloadRequiredFields() {");
    lines.push("        val payload = ConflictPayload(");
    for (let i = 0; i < required.length; i++) {
      const f = required[i];
      const propName = toCamelCase(f.name);
      const comma = i < required.length - 1 ? "," : "";
      let defaultVal = "\"test\"";
      if (f.type.startsWith("Map")) defaultVal = "mapOf(\"a\" to 1)";
      else if (f.type.startsWith("List")) defaultVal = "listOf(\"f1\")";
      else if (f.type === "ReportSnapshot") defaultVal = "\"snapshot\"";
      else if (f.type === "VectorClock") defaultVal = "mapOf(\"a\" to 1)";
      lines.push(`            ${propName} = ${defaultVal}${comma}`);
    }
    lines.push("        )");
    for (const f of required) {
      const propName = toCamelCase(f.name);
      lines.push(`        assert(payload.${propName} != null)`);
    }
    lines.push("    }");
  }

  lines.push("}");

  return lines.join("\n");
}

