function generateInterfaces(pkg: ImplementationHandoffPackage): string {
  const lines: string[] = [];

  // ConflictResolutionResult (return type for ConflictResolver)
  lines.push("/** Result of conflict resolution */");
  lines.push("data class ConflictResolutionResult(");
  lines.push("    val resolution: ConflictResolutionState,");
  lines.push("    val mergedFields: Map<String, String>,");
  lines.push("    val requiresClinician: Boolean,");
  lines.push("    val auditEventGenerated: Boolean");
  lines.push(")\n");

  for (const task of pkg.implementation_tasks) {
    const iface = INTERFACE_MAP[task.task_id];
    if (!iface) continue;

    // Find forbidden assumptions relevant to this task
    const relevantFA = pkg.forbidden_assumptions.filter(fa =>
      fa.statement.toLowerCase().includes(iface.name.toLowerCase().replace("repository", "").replace("runner", "").replace("manager", ""))
    );

    lines.push(`/**`);
    lines.push(` * ${task.title}`);
    lines.push(` * Source: ${task.task_id}`);
    if (relevantFA.length > 0) {
      lines.push(` *`);
      lines.push(` * FORBIDDEN ASSUMPTIONS:`);
      for (const fa of relevantFA) {
        lines.push(` *   ${fa.assumption_id}: ${fa.statement.substring(0, 120)}...`);
      }
    }
    lines.push(` */`);
    lines.push(`interface ${iface.name} {`);
    for (const m of iface.methods) {
      lines.push(`    /** ${m.doc} */`);
      const susp = m.suspend ? "suspend " : "";
      lines.push(`    ${susp}fun ${m.name}(${m.params}): ${m.returnType}`);
      lines.push("");
    }
    lines.push("}\n");
  }

  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// P13: Abstract Base Classes
// ---------------------------------------------------------------------------

function generateAbstractBases(pkg: ImplementationHandoffPackage): string {
  const lines: string[] = [];

  // BaseSyncWorker
  lines.push("/**");
  lines.push(" * Base class for sync workers. Provides guardrails:");
  lines.push(" * - Validates state transitions before execution");
  lines.push(" * - Enforces conflict policy at sync boundary");
  lines.push(" * - Requires audit events for conflict transitions");
  lines.push(" * - Forbids silent overwrite (FA-002)");
  lines.push(" */");
  lines.push("abstract class BaseSyncWorker(");
  lines.push("    private val repository: PendingReportRepository,");
  lines.push("    private val auditWriter: AuditEventWriter,");
  lines.push("    private val guards: PantheonGuards");
  lines.push(") {");
  lines.push("");
  lines.push("    suspend fun runSyncCycle(reportId: String): SyncUploadResult {");
  lines.push("        val report = repository.findById(reportId)");
  lines.push("            ?: throw IllegalArgumentException(\"Report not found: \\$reportId\")");
  lines.push("");
  lines.push("        // Guardrail: validate state transition");
  lines.push("        guards.requireValidTransition(\"PendingReportState\",");
  lines.push("            report.status, PendingReportState.syncing.name)");
  lines.push("");
  lines.push("        // Guardrail: audit the sync attempt");
  lines.push("        auditWriter.write(\"system\", \"sync_attempt\", reportId, null)");
  lines.push("");
  lines.push("        return executeSyncCycle(report)");
  lines.push("    }");
  lines.push("");
  lines.push("    protected abstract suspend fun executeSyncCycle(report: PendingReportEntity): SyncUploadResult");
  lines.push("}");
  lines.push("");

  // BaseConflictResolver
  lines.push("/**");
  lines.push(" * Base class for conflict resolvers. Provides guardrails:");
  lines.push(" * - Clinical fields NEVER use LWW (FA-001, FA-008)");
  lines.push(" * - Overlapping clinical fields → clinician review (FA-008)");
  lines.push(" * - Audit event for every conflict resolution (FA-006)");
  lines.push(" */");
  lines.push("abstract class BaseConflictResolver(");
  lines.push("    private val guards: PantheonGuards");
  lines.push(") : ConflictResolver {");
  lines.push("");
  lines.push("    override fun resolve(");
  lines.push("        local: OfflineReportEnvelope,");
  lines.push("        remote: OfflineReportEnvelope,");
  lines.push("        conflictPayload: ConflictPayload");
  lines.push("    ): ConflictResolutionResult {");
  lines.push("        // Guardrail: verify no clinical LWW");
  lines.push("        val fieldPolicies = classifyFields(conflictPayload.conflictingFields)");
  lines.push("        for ((field, policy) in fieldPolicies) {");
  lines.push("            guards.requireNoClinicalLww(field, policy.name)");
  lines.push("        }");
  lines.push("");
  lines.push("        // Guardrail: no silent overwrite");
  lines.push("        guards.requireNoSilentOverwrite(local.vectorClock, remote.vectorClock)");
  lines.push("");
  lines.push("        // Guardrail: non-empty conflicting fields");
  lines.push("        guards.requireNonEmptyConflictingFields(conflictPayload)");
  lines.push("");
  lines.push("        return executeResolution(local, remote, conflictPayload, fieldPolicies)");
  lines.push("    }");
  lines.push("");
  lines.push("    protected abstract fun executeResolution(");
  lines.push("        local: OfflineReportEnvelope,");
  lines.push("        remote: OfflineReportEnvelope,");
  lines.push("        conflictPayload: ConflictPayload,");
  lines.push("        fieldPolicies: Map<String, ConflictPolicy>");
  lines.push("    ): ConflictResolutionResult");
  lines.push("}");

  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// P13: Guard Functions
// ---------------------------------------------------------------------------

function generateGuards(pkg: ImplementationHandoffPackage): string {
  const lines: string[] = [];

  // Collect clinical field groups
  const clinicalGroups = pkg.conflict_policy_matrix
    .filter(cpm => cpm.policy === "vector_clock" && cpm.risk_level === "high")
    .map(cpm => cpm.field_group);

  lines.push("/**");
  lines.push(" * Pantheon-generated runtime guards.");
  lines.push(" * These enforce handoff invariants that implementations MUST NOT bypass.");
  lines.push(" *");
  lines.push(" * Source: handoff_package.json (forbidden_assumptions + conflict_policy_matrix + state_machines)");
  lines.push(" */");
  lines.push("object PantheonGuards {");
  lines.push("");

  // Guard 1: No clinical LWW
  lines.push("    private val clinicalFieldGroups = setOf(");
  lines.push(clinicalGroups.map(g => `        "${g}"`).join(",\n"));
  lines.push("    )");
  lines.push("");
  lines.push("    /**");
  lines.push("     * FA-001: Clinical fields must NEVER use LWW.");
  lines.push("     * Enforces: vector_clock policy for patient_case_status, vet_note_summary,");
  lines.push("     * triage_report_body, risk_level, suspected_condition.");
  lines.push("     */");
  lines.push("    fun requireNoClinicalLww(fieldGroup: String, policy: String) {");
  lines.push("        if (fieldGroup in clinicalFieldGroups && policy == \"last_writer_wins\") {");
  lines.push("            throw IllegalArgumentException(");
  lines.push("                \"FA-001 violation: Clinical field group '\\$fieldGroup' must not use LWW. \" +");
  lines.push("                \"Required policy: vector_clock\"");
  lines.push("            )");
  lines.push("        }");
  lines.push("    }");
  lines.push("");

  // Guard 2: Valid state transition
  lines.push("    /**");
  lines.push("     * FA-005: No invented states or transitions outside defined state machines.");
  lines.push("     */");
  lines.push("    fun requireValidTransition(machineName: String, from: String, to: String) {");
  lines.push("        val machine = when (machineName) {");
  lines.push("            \"PendingReportState\" -> PendingReportStateMachine");
  lines.push("            \"SyncOperationState\" -> SyncOperationStateMachine");
  lines.push("            \"ConflictResolutionState\" -> ConflictResolutionStateMachine");
  lines.push("            else -> throw IllegalArgumentException(\"Unknown state machine: \\$machineName\")");
  lines.push("        }");
  lines.push("        // Delegate to machine's requireAllowedTransition via enum lookup");
  lines.push("        when (machineName) {");

  for (const sm of pkg.state_machines) {
    lines.push(`            "${sm.name}" -> ${sm.name}Machine.requireAllowedTransition(`);
    lines.push(`                ${sm.name}.valueOf(from), ${sm.name}.valueOf(to))`);
  }
  lines.push("            else -> {}");
  lines.push("        }");
  lines.push("    }");
  lines.push("");

  // Guard 3: Audit for conflict
  lines.push("    /**");
  lines.push("     * FA-006: Every conflict detection/resolution must generate audit event.");
  lines.push("     */");
  lines.push("    fun requireAuditForConflict(auditGenerated: Boolean, conflictId: String) {");
  lines.push("        if (!auditGenerated) {");
  lines.push("            throw IllegalStateException(");
  lines.push("                \"FA-006 violation: Conflict '\\$conflictId' resolved without audit event.\"");
  lines.push("            )");
  lines.push("        }");
  lines.push("    }");
  lines.push("");

  // Guard 4: No silent overwrite
  lines.push("    /**");
  lines.push("     * FA-002: Do not silently overwrite remote edits.");
  lines.push("     * If clocks diverge, conflict resolution is required.");
  lines.push("     */");
  lines.push("    fun requireNoSilentOverwrite(localClock: Map<String, Int>, remoteClock: Map<String, Int>) {");
  lines.push("        val diverged = localClock.any { (actor, seq) -> remoteClock[actor] != null && remoteClock[actor] != seq }");
  lines.push("        if (diverged) {");
  lines.push("            // Clocks diverge — caller must go through conflict resolution, not direct overwrite");
  lines.push("            // This guard does not throw; it is an assertion the caller checks before writing");
  lines.push("        }");
  lines.push("    }");
  lines.push("");

  // Guard 5: Non-empty conflicting fields
  lines.push("    /**");
  lines.push("     * ConflictPayload.conflicting_fields must not be empty.");
  lines.push("     */");
  lines.push("    fun requireNonEmptyConflictingFields(payload: ConflictPayload) {");
  lines.push("        if (payload.conflictingFields.isEmpty()) {");
  lines.push("            throw IllegalArgumentException(");
  lines.push("                \"ConflictPayload.conflicting_fields must not be empty for report '\\${payload.reportId}'\"");
  lines.push("            )");
  lines.push("        }");
  lines.push("    }");

  lines.push("}");

  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// P13: Retry/Backoff Policy Table
// ---------------------------------------------------------------------------

function generateRetryPolicy(pkg: ImplementationHandoffPackage): string {
  const lines: string[] = [];

  lines.push("/**");
  lines.push(" * Deterministic retry/backoff policy derived from handoff.");
  lines.push(" * Source: TASK-004 acceptance criteria + state_machines");
  lines.push(" */");
  lines.push("object RetryBackoffPolicy {");
  lines.push("    const val INITIAL_DELAY_MS: Long = 1000");
  lines.push("    const val BACKOFF_MULTIPLIER: Double = 2.0");
  lines.push("    const val MAX_RETRIES: Int = 5");
  lines.push("    const val MAX_DELAY_MS: Long = 60000");
  lines.push("");
  lines.push("    /**");
  lines.push("     * Calculate next retry delay using exponential backoff.");
  lines.push("     * Doubles on each failure, capped at MAX_DELAY_MS.");
  lines.push("     */");
  lines.push("    fun nextDelay(attemptNumber: Int): Long {");
  lines.push("        if (attemptNumber >= MAX_RETRIES) return -1 // Terminal");
  lines.push("        val delay = (INITIAL_DELAY_MS * Math.pow(BACKOFF_MULTIPLIER, attemptNumber.toDouble())).toLong()");
  lines.push("        return minOf(delay, MAX_DELAY_MS)");
  lines.push("    }");
  lines.push("");
  lines.push("    /**");
  lines.push("     * Should this report transition to failed_terminal?");
  lines.push("     */");
  lines.push("    fun isTerminal(attemptNumber: Int): Boolean = attemptNumber >= MAX_RETRIES");
  lines.push("}");

  return lines.join("\n");
}

