// ---------------------------------------------------------------------------
// P13: TODO Stubs
// ---------------------------------------------------------------------------

function generateTodoStubs(pkg: ImplementationHandoffPackage): string {
  const lines: string[] = [];

  const stubTasks = pkg.implementation_tasks.filter(t =>
    ["TASK-002", "TASK-003", "TASK-004", "TASK-005", "TASK-006", "TASK-007"].includes(t.task_id)
  );

  for (const task of stubTasks) {
    const iface = INTERFACE_MAP[task.task_id];
    if (!iface) continue;

    lines.push(`/**`);
    lines.push(` * TODO stub for ${task.title}`);
    lines.push(` * Source: ${task.task_id}`);
    lines.push(` */`);
    lines.push(`class Todo${iface.name} : ${iface.name} {`);

    for (const m of iface.methods) {
      const susp = m.suspend ? "suspend " : "";
      lines.push(`    override ${susp}fun ${m.name}(${m.params}): ${m.returnType} {`);

      // Build acceptance criteria string
      const criteria = task.acceptance_criteria.map(c => `     *   - ${c}`).join("\n");
      lines.push(`        TODO(`);
      lines.push(`            """`);
      lines.push(`            Implement: ${task.title}`);
      lines.push(`            Source: ${task.task_id}`);
      lines.push(`            `);
      lines.push(`            Acceptance criteria:`);
      for (const c of task.acceptance_criteria) {
        lines.push(`              - ${c}`);
      }
      lines.push(`            """.trimIndent()`);
      lines.push(`        )`);
      lines.push(`    }`);
      lines.push("");
    }

    lines.push("}");
    lines.push("");
  }

  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export type KotlinGeneratorOutput = {
  files: Array<{
    fileName: string;
    content: string;
  }>;
  metrics: {
    entity_count: number;
    dto_count: number;
    enum_count: number;
    state_machine_count: number;
    conflict_policy_groups: number;
    total_fields: number;
    allowed_transitions: number;
    forbidden_transitions: number;
    // P13
    interface_count: number;
    guard_count: number;
    contract_test_count: number;
    todo_stub_count: number;
  };
  package_hash: string;
};

export function generateKotlin(
  pkg: ImplementationHandoffPackage,
): KotlinGeneratorOutput {
  // Compute package hash for provenance
  const pkgHash = createHash("sha256")
    .update(JSON.stringify(pkg))
    .digest("hex")
    .slice(0, 16);

  const header = (name: string) => generateHeader(pkg, name, pkgHash);

  // Generate all files
  const enumsContent = generateEnums(pkg);
  const entitiesContent = generateEntities(pkg);
  const dtosContent = generateDtos(pkg);
  const stateMachinesContent = generateStateMachines(pkg);
  const conflictPolicyContent = generateConflictPolicy(pkg);
  const testsContent = generateConflictPolicyTests(pkg);

  // P13: Generate contract boundary files
  const interfacesContent = generateInterfaces(pkg);
  const abstractBasesContent = generateAbstractBases(pkg);
  const guardsContent = generateGuards(pkg);
  const retryPolicyContent = generateRetryPolicy(pkg);
  const contractTestsContent = generateContractTests(pkg);
  const todoStubsContent = generateTodoStubs(pkg);

  // Contract header (read-only warning)
  const contractHeader = (name: string) =>
    generateHeader(pkg, `contracts/${name}`, pkgHash)
      + "// READ-ONLY — DO NOT EDIT. Fix the source artifact, then regenerate.\n\n";

  // Collect metrics
  const entities = pkg.data_models.filter(dm => dm.kind === "room_entity");
  const dtos = pkg.data_models.filter(dm => dm.kind === "network_dto");
  const enumCount = pkg.state_machines.length
    + pkg.contract_definitions.filter(cd =>
      cd.enum_values && cd.enum_values.length > 0
      && !pkg.state_machines.some(sm => sm.name === cd.term.split("_").map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(""))
    ).length
    + 1; // ConflictPolicy enum

  const totalFields = pkg.data_models.reduce((sum, dm) => sum + dm.fields.length, 0);
  const allowedTransitions = pkg.state_machines.reduce(
    (sum, sm) => sum + sm.allowed_transitions.length, 0
  );
  const forbiddenTransitions = pkg.state_machines.reduce(
    (sum, sm) => sum + sm.forbidden_transitions.length, 0
  );

  // P13 metrics
  const interfaceCount = Object.keys(INTERFACE_MAP).length;
  const guardCount = 5; // requireNoClinicalLww, requireValidTransition, requireAuditForConflict, requireNoSilentOverwrite, requireNonEmptyConflictingFields
  const contractTestClassCount = 5;
  const todoStubCount = pkg.implementation_tasks.filter(t =>
    ["TASK-002", "TASK-003", "TASK-004", "TASK-005", "TASK-006", "TASK-007"].includes(t.task_id)
  ).length;

  return {
    files: [
      // P12: Data layer
      { fileName: "Enums.kt", content: header("Enums.kt") + enumsContent },
      { fileName: "Entities.kt", content: header("Entities.kt") + entitiesContent },
      { fileName: "Dtos.kt", content: header("Dtos.kt") + dtosContent },
      { fileName: "StateMachines.kt", content: header("StateMachines.kt") + stateMachinesContent },
      { fileName: "ConflictPolicy.kt", content: header("ConflictPolicy.kt") + conflictPolicyContent },
      { fileName: "ConflictPolicyTests.kt", content: header("ConflictPolicyTests.kt") + testsContent },
      // P13: Contract boundary layer
      { fileName: "contracts/Interfaces.kt", content: contractHeader("Interfaces.kt") + interfacesContent },
      { fileName: "contracts/AbstractBases.kt", content: contractHeader("AbstractBases.kt") + abstractBasesContent },
      { fileName: "contracts/Guards.kt", content: contractHeader("Guards.kt") + guardsContent },
      { fileName: "contracts/RetryPolicy.kt", content: contractHeader("RetryPolicy.kt") + retryPolicyContent },
      { fileName: "contracts/ContractTests.kt", content: contractHeader("ContractTests.kt") + contractTestsContent },
      { fileName: "contracts/TodoStubs.kt", content: contractHeader("TodoStubs.kt") + todoStubsContent },
    ],
    metrics: {
      entity_count: entities.length,
      dto_count: dtos.length,
      enum_count: enumCount,
      state_machine_count: pkg.state_machines.length,
      conflict_policy_groups: pkg.conflict_policy_matrix.length,
      total_fields: totalFields,
      allowed_transitions: allowedTransitions,
      forbidden_transitions: forbiddenTransitions,
      // P13 metrics
      interface_count: interfaceCount,
      guard_count: guardCount,
      contract_test_count: contractTestClassCount,
      todo_stub_count: todoStubCount,
    },
    package_hash: pkgHash,
  };
}
